commit f7f5dc45e51c56f20b4796b77b58d6e257c5fc29
Author: Liz <liz@gewelf.com>
Date:   Fri Oct 30 22:56:09 2026 -0400

    perf(read): zero-copy byte arrays on flat reads

    BYTE_ARRAY values decoded from PLAIN and dictionary pages (V1 and V2) are
    now slices of the page buffer or dictionary page instead of per-value
    copies. readColumnDynamicWithData enables this (column_decoder.borrow_bytes)
    only when it owns the page buffers and value_mod.bytes_arena_allocator is
    set: it then allocates the uncompressed chunk, or each decompressed page,
    from that arena and never frees them, and builds the string dictionary with
    StringDictionary.fromPlainBorrowed. Borrowed bytes therefore live exactly
    as long as the arena copies did: until the streaming iterator's per-row-group
    reset, or the reader's bytes arena deinit for readAllRows/rowIterator.
    Value.deinit already skips bytes in that scope and rows are bytes_borrowed.
    Filtered reads (caller-owned page data), FLBA, decimals, delta encodings,
    arrow_batch and the typed decoder keep copying.

    Also re-exports StreamingRowIterator from lib.zig.

    make bench (0.16, ReleaseFast), best of 6 alternating runs, rows/s:
                      read_stream          read                 write
      int64_plain     151.3M -> 148.0M     45.4M -> 44.9M       56.9M -> 55.9M
      f64_plain       151.0M -> 148.5M     45.2M -> 44.6M       56.3M -> 55.8M
      int64_nullable  132.7M -> 134.4M     43.5M -> 43.5M       75.9M -> 75.0M
      str_dict         49.8M ->  79.9M     28.0M -> 35.9M       18.4M -> 18.3M
      str_unique       46.3M ->  70.0M     26.9M -> 33.8M       13.3M -> 13.2M
      mixed5           21.1M ->  25.2M     10.5M -> 11.5M        4.9M ->  4.9M
    file_MB unchanged for every scenario.

    Co-Authored-By: Claude Fable 5.1 <noreply@anthropic.com>
    Entire-Checkpoint: 01M67Y5N7T1GPNJYRMW4X8TS62

diff --git a/zig-parquet/src/core/column_decoder.zig b/zig-parquet/src/core/column_decoder.zig
index 8e231ff..0c3135c 100644
--- a/zig-parquet/src/core/column_decoder.zig
+++ b/zig-parquet/src/core/column_decoder.zig
@@ -24,6 +24,30 @@ pub const Optional = types.Optional;
 pub const Int96 = types.Int96;
 pub const Value = value_mod.Value;

+/// Byte ownership for variable-length BYTE_ARRAY values decoded from PLAIN and
+/// dictionary pages (V1 and V2; not FIXED_LEN_BYTE_ARRAY, decimals or delta
+/// encodings, which always copy).
+///
+/// - `false` (default): each `bytes_val` is a fresh copy made by
+///   `value_mod.dupeBytes`, so it outlives `value_data` and the dictionary.
+/// - `true`: each `bytes_val` is a slice of `value_data` or of the dictionary's
+///   entries (which must then be slices of the dictionary page buffer). The
+///   caller must keep those buffers alive for as long as the values, and must
+///   never free the slices individually. `DynamicReader` sets this only while
+///   `value_mod.bytes_arena_allocator` is set and the page buffers were
+///   allocated from that arena, so borrowed slices live exactly as long as
+///   arena copies would have and `Value.deinit` already skips them.
+///
+/// Every borrowed slice comes from a length-checked decode (`plain.decodeByteArray`
+/// / `PlainDecoder`), the same bounds the copying path relies on.
+pub threadlocal var borrow_bytes: bool = false;
+
+/// Copy `bytes` (or return them as-is when `borrow_bytes` is set).
+inline fn takeBytes(allocator: std.mem.Allocator, bytes: []const u8) std.mem.Allocator.Error![]const u8 {
+    if (borrow_bytes) return bytes;
+    return value_mod.dupeBytes(allocator, bytes);
+}
+
 /// Extract and validate bit_width from dictionary-encoded data.
 /// Bit width must be 0-31 to fit in u5 for RLE decoding.
 fn extractBitWidth(data: []const u8, offset: usize) error{ InvalidBitWidth, EndOfData }!u5 {
@@ -441,9 +465,9 @@ fn decodeDictStringsWithDefLevels(
             const dict_idx = indices[idx_pos];
             idx_pos += 1;
             if (ctx.string_dict.?.get(dict_idx)) |v| {
-                result[i] = .{ .value = try value_mod.dupeBytes(ctx.allocator, v) };
+                result[i] = .{ .value = try takeBytes(ctx.allocator, v) };
             } else {
-                result[i] = .{ .value = try value_mod.dupeBytes(ctx.allocator, "") };
+                result[i] = .{ .value = try takeBytes(ctx.allocator, "") };
             }
         } else {
             result[i] = .{ .null_value = {} };
@@ -698,7 +722,7 @@ fn decodePlainWithDefLevels(
                     if (data_offset + 4 > value_data.len) return error.EndOfData;
                     const ba = try plain.decodeByteArray(value_data[data_offset..]);
                     if (data_offset + ba.bytes_read > value_data.len) return error.EndOfData;
-                    result[i] = .{ .value = try value_mod.dupeBytes(ctx.allocator, ba.value) };
+                    result[i] = .{ .value = try takeBytes(ctx.allocator, ba.value) };
                     data_offset += ba.bytes_read;
                 }
             } else if (T == Int96) {
@@ -749,9 +773,9 @@ fn decodeRequiredColumn(

         for (0..ctx.num_values) |i| {
             if (ctx.string_dict.?.get(indices[i])) |v| {
-                result[i] = .{ .value = try value_mod.dupeBytes(ctx.allocator, v) };
+                result[i] = .{ .value = try takeBytes(ctx.allocator, v) };
             } else {
-                result[i] = .{ .value = try value_mod.dupeBytes(ctx.allocator, "") };
+                result[i] = .{ .value = try takeBytes(ctx.allocator, "") };
             }
         }
     } else if (ctx.uses_dict and T == i32) {
@@ -841,7 +865,7 @@ fn decodeRequiredColumn(
             if (decoder.next()) |v| {
                 // For byte arrays, we need to dupe since value_data may be freed
                 if (T == []const u8) {
-                    result[i] = .{ .value = try value_mod.dupeBytes(ctx.allocator, v) };
+                    result[i] = .{ .value = try takeBytes(ctx.allocator, v) };
                 } else {
                     result[i] = .{ .value = v };
                 }
@@ -1543,9 +1567,9 @@ fn decodeDynamicByteArrayV2(allocator: std.mem.Allocator, values_data: []const u
         for (0..num_values) |i| {
             if (def_mask[i]) {
                 if (string_dict.?.get(indices[idx_pos])) |v| {
-                    values[i] = .{ .bytes_val = try value_mod.dupeBytes(allocator, v) };
+                    values[i] = .{ .bytes_val = try takeBytes(allocator, v) };
                 } else {
-                    values[i] = .{ .bytes_val = try value_mod.dupeBytes(allocator, "") };
+                    values[i] = .{ .bytes_val = try takeBytes(allocator, "") };
                 }
                 idx_pos += 1;
             } else {
@@ -1557,7 +1581,7 @@ fn decodeDynamicByteArrayV2(allocator: std.mem.Allocator, values_data: []const u
         for (0..num_values) |i| {
             if (def_mask[i]) {
                 const ba = try plain.decodeByteArray(values_data[data_offset..]);
-                values[i] = .{ .bytes_val = try value_mod.dupeBytes(allocator, ba.value) };
+                values[i] = .{ .bytes_val = try takeBytes(allocator, ba.value) };
                 data_offset += ba.bytes_read;
             } else {
                 values[i] = .{ .null_val = {} };
diff --git a/zig-parquet/src/core/dynamic_reader.zig b/zig-parquet/src/core/dynamic_reader.zig
index 59d2c8f..c87a1fb 100644
--- a/zig-parquet/src/core/dynamic_reader.zig
+++ b/zig-parquet/src/core/dynamic_reader.zig
@@ -875,12 +875,33 @@ pub const DynamicReader = struct {
         const chunk = &rg.columns[column_index];
         const meta = chunk.meta_data orelse return error.InvalidArgument;

+        // Zero-copy BYTE_ARRAY values (see `column_decoder.borrow_bytes`): when
+        // byte payloads go to a bytes arena and this function owns the page
+        // buffers, those buffers are allocated from that arena and decoded values
+        // point into them. They then live exactly as long as arena copies would
+        // have (until the arena's reset/deinit); nothing frees them per value.
+        const borrow_arena: ?std.mem.Allocator = if (override_page_data == null and
+            if (format.getColumnInfo(self.metadata.schema, column_index)) |ci| ci.element.type_ == .byte_array else false)
+            value_mod.bytes_arena_allocator
+        else
+            null;
+        const prev_borrow = column_decoder.borrow_bytes;
+        column_decoder.borrow_bytes = borrow_arena != null;
+        defer column_decoder.borrow_bytes = prev_borrow;
+        // Page buffers (decompressed pages, or the whole chunk when uncompressed)
+        // go to the arena when borrowing and are then never freed here: an arena
+        // free of its last allocation would hand the bytes to the next page.
+        const page_alloc = borrow_arena orelse self.allocator;
+        const free_pages = borrow_arena == null;
+        const chunk_alloc = if (meta.codec == .uncompressed) page_alloc else self.allocator;
+        const free_chunk = free_pages or meta.codec != .uncompressed;
+
         // Read the raw page data (or use caller's buffer).
         const owned_page_data: ?[]u8 = if (override_page_data == null)
-            try self.readColumnChunkData(chunk)
+            try self.readColumnChunkData(chunk_alloc, chunk)
         else
             null;
-        defer if (owned_page_data) |pd| self.allocator.free(pd);
+        defer if (owned_page_data) |pd| if (free_chunk) chunk_alloc.free(pd);
         const page_data: []const u8 = owned_page_data orelse override_page_data.?;

         var pos: usize = 0;
@@ -934,9 +955,9 @@ pub const DynamicReader = struct {

                 // Decompress dictionary page if needed
                 const dict_data = if (meta.codec != .uncompressed) blk: {
-                    break :blk try self.decompressData(dict_compressed, meta.codec, dict_uncompressed_size);
+                    break :blk try self.decompressData(page_alloc, dict_compressed, meta.codec, dict_uncompressed_size);
                 } else dict_compressed;
-                defer if (meta.codec != .uncompressed) self.allocator.free(dict_data);
+                defer if (meta.codec != .uncompressed and free_pages) self.allocator.free(dict_data);

                 // Build dictionaries based on physical type
                 const column_info_for_dict = format.getColumnInfo(self.metadata.schema, column_index);
@@ -944,7 +965,10 @@ pub const DynamicReader = struct {
                     if (info.element.type_) |phys_type| {
                         switch (phys_type) {
                             .byte_array => {
-                                string_dict = try dictionary.StringDictionary.fromPlain(self.allocator, dict_data, dict_num_values);
+                                string_dict = if (borrow_arena != null)
+                                    try dictionary.StringDictionary.fromPlainBorrowed(self.allocator, dict_data, dict_num_values)
+                                else
+                                    try dictionary.StringDictionary.fromPlain(self.allocator, dict_data, dict_num_values);
                             },
                             .int32 => {
                                 int32_dict = try dictionary.Int32Dictionary.fromPlain(self.allocator, dict_data, dict_num_values);
@@ -1058,9 +1082,9 @@ pub const DynamicReader = struct {
                         break :blk values_compressed; // Return empty slice, no decompression needed
                     }
                     values_data_allocated = true;
-                    break :blk try self.decompressData(values_compressed, meta.codec, values_uncompressed_size);
+                    break :blk try self.decompressData(page_alloc, values_compressed, meta.codec, values_uncompressed_size);
                 } else values_compressed;
