const std = @import("std");
const parquet = @import("../lib.zig");
const io = std.testing.io;

fn check(path: []const u8, b: []const u8, nb: *usize, naa: *usize) void {
    nb.* += 1;
    if (b.len > 0 and std.mem.allEqual(u8, b, 0xaa)) naa.* += 1;
    if (nb.* < 3) std.debug.print("REVIEW-SAMPLE {s} {x}|", .{ path, b[0..@min(b.len, 16)] });
}

fn scanFile(allocator: std.mem.Allocator, path: []const u8) !void {
    const file = std.Io.Dir.cwd().openFile(io, path, .{}) catch return;
    defer file.close(io);
    var dyn = parquet.openFileDynamic(allocator, file, io, .{}) catch return;
    defer dyn.deinit();
    var nb: usize = 0;
    var naa: usize = 0;
    defer std.debug.print("REVIEW-COUNT {s} bytes={d} allAA={d}|", .{ path, nb, naa });
    for (0..dyn.getNumRowGroups()) |rg| {
        const rows = dyn.readAllRows(rg) catch return;
        defer {
            for (rows) |r| r.deinit();
            allocator.free(rows);
        }
        for (rows) |r| for (r.values) |v| switch (v) {
            .bytes_val => |b| check(path, b, &nb, &naa),
            else => {},
        };
    }
    var it = dyn.rowIteratorStreaming();
    defer it.deinit();
    while (it.next() catch null) |r| {
        for (r.values) |v| switch (v) {
            .bytes_val => |b| check(path, b, &nb, &naa),
            else => {},
        };
    }
}

test "review scan" {
    const allocator = std.testing.allocator;
    const dirs = [_][]const u8{ "../test-files-wild/parquet-testing/data", "../test-files-wild" };
    for (dirs) |d| {
        var dir = std.Io.Dir.cwd().openDir(io, d, .{ .iterate = true }) catch continue;
        defer dir.close(io);
        var iter = dir.iterate();
        while (try iter.next(io)) |e| {
            if (!std.mem.endsWith(u8, e.name, ".parquet")) continue;
            const path = try std.fmt.allocPrint(allocator, "{s}/{s}", .{ d, e.name });
            defer allocator.free(path);
            try scanFile(allocator, path);
        }
    }
}

test "review v2 uncompressed-flag page under compressed codec" {
    const allocator = std.testing.allocator;
    const file = try std.Io.Dir.cwd().openFile(io, "../test-files-wild/v2_none_plain.parquet", .{});
    defer file.close(io);
    var good = try parquet.openFileDynamic(allocator, file, io, .{});
    defer good.deinit();
    const want = try good.readAllRows(0);
    defer {
        for (want) |r| r.deinit();
        allocator.free(want);
    }

    var bad = try parquet.openFileDynamic(allocator, file, io, .{});
    defer bad.deinit();
    // Same bytes, but the chunk claims SNAPPY: the V2 page header's is_compressed=false
    // means the values are read straight from the (gpa-owned, freed) chunk buffer.
    bad.metadata.row_groups[0].columns[0].meta_data.?.codec = .snappy;
    const got = try bad.readAllRows(0);
    defer {
        for (got) |r| r.deinit();
        allocator.free(got);
    }
    var mismatches: usize = 0;
    for (want, got) |w, g| {
        if (!std.mem.eql(u8, w.values[0].bytes_val, g.values[0].bytes_val)) mismatches += 1;
    }
    std.debug.print("REVIEW-V2 rows={d} mismatches={d} first_got={x}|", .{ got.len, mismatches, got[0].values[0].bytes_val[0..@min(16, got[0].values[0].bytes_val.len)] });
    try std.testing.expectEqual(@as(usize, 0), mismatches);
}

